import pandas as pd
from scipy.special import expit
from common import *
def run():
 out=ROOT/'outputs/r97';rec=json.loads((out/'receipt.json').read_text())
 for p,h in rec['reads'].items():assert sha(p)==h,p
 folds=json.loads((out/'folds.json').read_text());original_models=json.loads((ROOT/'outputs/r02/model_parameters.json').read_text());ca=pd.read_parquet(out/'calibration_rows.parquet');te=pd.read_parquet(out/'predictions.parquet');old=pd.read_parquet(ROOT/'data/r09_daily_scores.parquet');old=old[old.eligible];keys=KEY+['date'];joined=te.merge(old[keys+['score','y','maturity20']],on=keys,how='outer',suffixes=('','_old'),indicator=True,validate='one_to_one');assert joined._merge.eq('both').all() and np.allclose(joined.monthly_probability,joined.score,atol=1e-10,rtol=0) and np.allclose(joined.y,joined.y_old,equal_nan=True);assert joined.maturity20.fillna(pd.Timestamp(1900,1,1)).eq(joined.maturity20_old.fillna(pd.Timestamp(1900,1,1))).all()
 raw=pd.read_parquet(CACHE/'forecast_v5/daily_industries.parquet');market=pd.read_parquet(CACHE/'forecast_v5/CSI_ALL.parquet').close;parts=[];cols=['mom20','mom60','vol20','dd60','past_excess20','past_excess60','log_members']
 for _,g in raw.groupby(KEY+['block']):
  g=g.sort_values('date').copy();nav=g.nav;b=g.date.map(market);g['mom20']=nav/nav.shift(20)-1;g['mom60']=nav/nav.shift(60)-1;g['vol20']=(nav/nav.shift(1)-1).rolling(20).std()*np.sqrt(252);g['dd60']=nav/nav.rolling(60).max()-1;g['past_excess20']=g.mom20-(b/b.shift(20)-1);g['past_excess60']=g.mom60-(b/b.shift(60)-1);g['log_members']=np.log(g.members);ret=nav.shift(-21)/nav.shift(-1)-1;ex=ret-(b.shift(-21)/b.shift(-1)-1);g['y']=((ret>=.05)&(ex>=.03)).astype(float).where(ex.notna());g['maturity20']=g.date.shift(-21);g=g[g[cols].notna().all(axis=1)&g.coverage.ge(.8)&g.members.ge(5)];parts.append(g[keys+cols+['y','maturity20']])
 ready=pd.concat(parts,ignore_index=True);grouped=ready.groupby(['era','level','date'])[cols];ranks=(grouped.rank(method='average')-.5)/grouped.transform('count')-.5
 for f in folds:
  m=f['base_model'];assert m in original_models;start=pd.Timestamp(f['year']-1,7,1);boundary=pd.Timestamp(f['year'],1,1);assert pd.Timestamp(m['fit_max_maturity'])<start;g=ready[ready.era.eq(f['era'])&ready.level.eq(f['level'])&ready.date.ge(start)&ready.date.lt(boundary)&ready.maturity20.lt(boundary)&ready.y.notna()&ready.past_excess20.le(0)].copy();c=ca[ca.era.eq(f['era'])&ca.level.eq(f['level'])&ca.model_year.eq(f['year'])];assert len(c)==len(g)==f['cal_rows'];assert set(map(tuple,c[keys].to_numpy()))==set(map(tuple,g[keys].to_numpy()));assert f['cal_months']==g.date.dt.to_period('M').nunique()>=4 and len(g)>=100 and g.y.value_counts().min()>=10;assert f['cal_dates']==g.date.nunique() and pd.Timestamp(f['cal_max_maturity'])==g.maturity20.max()<boundary
  xx=(ranks.loc[g.index,m['columns']].to_numpy()-np.array(m['scaler_mean']))/np.array(m['scaler_scale']);g['linear_check']=xx@np.array(m['coefficient']).reshape(-1)+m['intercept'][0];z=c.merge(g[keys+['linear_check','y']],on=keys,validate='one_to_one',suffixes=('','_check'));assert np.allclose(z.linear,z.linear_check,rtol=1e-12,atol=1e-12) and np.array_equal(z.y,z.y_check);w=m['n_cal']/(len(set(c.date))*c.groupby('date').date.transform('size'));assert np.allclose(c.weight,w) and np.isclose(sum(c.weight),m['n_cal']);residual=expit(f['coefficient']*c.linear+f['intercept'])-c.y;grad=np.array([sum(c.weight*residual*c.linear)+f['coefficient'],sum(c.weight*residual)])/sum(c.weight);assert np.max(np.abs(grad))<.0005 and f['iterations']<2000
  q=te[te.era.eq(f['era'])&te.level.eq(f['level'])&te.year.eq(f['year'])];assert np.allclose(q.daily_probability,expit(f['coefficient']*q.linear+f['intercept']),atol=1e-12)
 for s in json.loads((out/'summary.json').read_text()):
  q=te[te.era.eq(s['era'])&te.level.eq(s['level'])&te.year.eq(s['year'])];v=q[q.y.notna()];p=v[s['method']+'_probability'].clip(1e-15,1-1e-15);assert s['rows']==len(q) and s['mature']==len(v) and s['unknown']==len(q)-len(v) and s['dates']==v.date.nunique();data={'brier':(p-v.y)**2,'logloss':-(v.y*np.log(p)+(1-v.y)*np.log(1-p)),'gap':p-v.y}
  for name,values in data.items():assert np.isclose(s[name],values.groupby(v.date).mean().mean(),atol=1e-12)
 for s in json.loads((out/'bins.json').read_text()):
  q=te[te.era.eq(s['era'])&te.level.eq(s['level'])&te.year.eq(s['year'])&te.y.notna()];p=q[s['method']+'_probability'];mask=np.minimum((p*10).astype(int),9)==s['bin'];assert s['rows']==mask.sum() and np.isclose(s['probability'],p[mask].mean()) and np.isclose(s['observed'],q.loc[mask,'y'].mean())
 js(out/'verification.json',dict(status='PASS',folds=len(folds),calibration_rows=len(ca),test_rows=len(te),scope='all original test probabilities/labels, independently rebuilt calibration features/ranks/maturity and model decisions, date weights, penalized likelihood gradient, predictions and metrics',verifier_sha256=sha(Path(__file__))));print('R97 VERIFIED',len(folds),len(ca),len(te))
if __name__=='__main__':run()
